public class MaClasse {
    private int x;
    // constructeur, méthodes...
}

public MaClasse(int x) {
    this.x = x;
}

// Plusieurs constructeurs (surcharge)
public MaClasse()        { this(0); }
public MaClasse(int x)   { this.x = x; }

public class Fils extends Parent {
    public Fils(int x) {
        super(x); // appel du constructeur parent
    }
}

@Override
public void methode() {
    super.methode(); // appel de la version parent
    // puis code supplémentaire
}

public abstract class A {
    public abstract void methode();       // doit être implémentée
    public void methodeConcrète() { ... } // optionnellement redéfinissable
}

public interface MonInterface {
    void methodeAbstraite();
    default void methodeDefaut() { ... }  // implémentation optionnelle
    static void methodeStatique() { ... } // accessible via MonInterface.methodeStatique()
}

public class C extends Parent implements Interface1, Interface2 {
    @Override public void methode() { ... }
}

if (obj instanceof MaClasse c) {
    // c est directement castée et disponible (Java 16+)
}

private int x;
public int getX()        { return x; }
public void setX(int x)  { this.x = x; }

public enum Couleur {
    ROUGE, VERT, BLEU
}
// Utilisation :
Couleur c = Couleur.ROUGE;
switch (c) { case ROUGE -> ... }

public enum Tier {
    WOOD(1, 59), IRON(2, 250), DIAMOND(3, 1561);

    final int level;
    final int durability;
    Tier(int level, int durability) {
        this.level = level;
        this.durability = durability;
    }
}

@Override
public String toString() {
    return "MaClasse{x=" + x + "}";
}

@Override
public boolean equals(Object o) {
    if (!(o instanceof MaClasse c)) return false;
    return x == c.x;
}

@Override
public int hashCode() { return Integer.hashCode(x); }

// Classe interne anonyme (implémentation ponctuelle)
Runnable r = new Runnable() {
    @Override public void run() { System.out.println("ok"); }
};
// Équivalent lambda :
Runnable r = () -> System.out.println("ok");

// Classe générique
public class Boite<T> {
    private T contenu;
    public Boite(T contenu) { this.contenu = contenu; }
    public T get() { return contenu; }
}
Boite<String> b = new Boite<>("hello");

// Méthode générique
public <T extends Comparable<T>> T max(T a, T b) {
    return a.compareTo(b) >= 0 ? a : b;
}
